#!/usr/bin/env python3
"""Upgrade test for every database migration, run in CI after the app is built.

1. Rebuilds the version 1 database: the tables no migration creates, as Room generates them
   today minus the columns later migrations add.
2. Puts a row in every table, applies each migration's SQL in order (Migrations.kt), and adds a
   row to each table a migration creates.
3. Checks the upgraded database matches a fresh one made from Room's generated schema (columns,
   types, NOT NULL, primary keys and indexes), every row survived, the chain has no gaps and the
   last step reaches AppDatabase's version.
"""
import pathlib
import re
import sqlite3
import sys

root = pathlib.Path(__file__).resolve().parents[2]
impls = list((root / "app/build/generated/ksp").rglob("AppDatabase_Impl.*"))
if not impls:
    sys.exit("AppDatabase_Impl not found; build the app first")
generated = impls[0].read_text()
migrations_src = (root / "app/src/main/kotlin/app/weathertrack/data/db/Migrations.kt").read_text()
database_src = (root / "app/src/main/kotlin/app/weathertrack/data/db/AppDatabase.kt").read_text()

statements = re.findall(r'"(CREATE (?:TABLE|INDEX|UNIQUE INDEX) IF NOT EXISTS [^"]+)"', generated)
statements = [s.replace('\\"', '"') for s in statements if "room_master_table" not in s]


def table_of(stmt):
    m = re.match(r"CREATE TABLE IF NOT EXISTS `(\w+)`", stmt)
    if m:
        return m.group(1)
    return re.search(r" ON `(\w+)`", stmt).group(1)


# Migrations in order: (from, to, [sql]).
steps = []
for m in re.finditer(r"Migration\((\d+), (\d+)\)\s*\{(.*?)\n    \}", migrations_src, re.S):
    sql = [s.replace('\\"', '"') for s in re.findall(r'execSQL\("((?:[^"\\]|\\.)*)"\)', m.group(3))]
    steps.append((int(m.group(1)), int(m.group(2)), sql))
steps.sort()
failed = False


def fail(msg):
    global failed
    print(msg)
    failed = True


version = int(re.search(r"version = (\d+)", database_src).group(1))
expected = 1
for a, b, _ in steps:
    if a != expected or b != a + 1:
        fail(f"Migration chain gap: found {a} -> {b}, expected {expected} -> {expected + 1}")
    expected = b
if expected != version:
    fail(f"Migrations end at version {expected} but AppDatabase is version {version}")
listed = re.search(r"val ALL = arrayOf\((.*?)\)", migrations_src, re.S).group(1)
for a, b, _ in steps:
    if f"MIGRATION_{a}_{b}" not in listed:
        fail(f"MIGRATION_{a}_{b} is not in Migrations.ALL")

created_later = {table_of(s) for _, _, sql in steps for s in sql if s.startswith("CREATE TABLE")}
altered = [(t, c, d) for _, _, sql in steps for s in sql
           for t, c, d in re.findall(r"ALTER TABLE `(\w+)` ADD COLUMN `(\w+)` ([A-Z]+(?: NOT NULL)?)", s)]


def v1(stmt):
    t = table_of(stmt)
    if stmt.startswith("CREATE TABLE"):
        for at, col, decl in altered:
            if at == t:
                stmt = stmt.replace(f", `{col}` {decl}", "")
    return stmt


def columns(db, table):
    return db.execute(f"PRAGMA table_info(`{table}`)").fetchall()


def sample_row(db, table, n):
    cols = columns(db, table)
    names, values = [], []
    for _, name, typ, notnull, _, pk in cols:
        if pk and typ == "INTEGER" and len([c for c in cols if c[5]]) == 1:
            continue  # rowid alias, autogenerated
        names.append(f"`{name}`")
        values.append({"INTEGER": 1000 + n, "REAL": 1.5 + n, "TEXT": f"t{n}", "BLOB": b"x"}.get(typ, None) if notnull or pk else None)
    db.execute(f"INSERT INTO `{table}` ({','.join(names)}) VALUES ({','.join('?' * len(values))})", values)


old = sqlite3.connect(":memory:")
first_tables = sorted({table_of(s) for s in statements} - created_later)
for s in statements:
    if table_of(s) in first_tables:
        old.execute(v1(s))
rows = {}
for t in first_tables:
    sample_row(old, t, 1)
    rows[t] = 1
for a, b, sql in steps:
    try:
        for s in sql:
            old.execute(s)
    except sqlite3.Error as e:
        fail(f"Migration {a} -> {b} failed: {e}")
        break
    for s in sql:
        if s.startswith("CREATE TABLE"):
            t = table_of(s)
            sample_row(old, t, b)
            rows[t] = rows.get(t, 0) + 1

fresh = sqlite3.connect(":memory:")
for s in statements:
    fresh.execute(s)


def shape(db):
    out = {}
    for (t,) in db.execute("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'"):
        cols = sorted((c[1], c[2], c[3], c[5]) for c in columns(db, t))
        idx = sorted(
            (i[1], i[2], tuple(c[2] for c in db.execute(f"PRAGMA index_info(`{i[1]}`)")))
            for i in db.execute(f"PRAGMA index_list(`{t}`)") if not i[1].startswith("sqlite_autoindex")
        )
        out[t] = (cols, idx)
    return out


a, b = shape(old), shape(fresh)
for t in sorted(set(a) | set(b)):
    if t not in a:
        fail(f"Table {t} is missing after upgrading")
    elif t not in b:
        fail(f"Table {t} exists after upgrading but Room doesn't expect it")
    elif a[t] != b[t]:
        fail(f"Table {t} differs after upgrading:\n  upgraded {a[t]}\n  expected {b[t]}")
for t, n in rows.items():
    got = old.execute(f"SELECT COUNT(*) FROM `{t}`").fetchone()[0]
    if got != n:
        fail(f"Table {t} has {got} rows after upgrading, expected {n}")

print(f"Upgraded version 1 -> {version} through {len(steps)} migrations: " + ("FAILED" if failed else "OK"))
sys.exit(1 if failed else 0)
